"use strict";
import { useAccount } from "hooks/useAccount";
import { useVeABXUserLocks } from "hooks/useVeABXLocks";
import { useVotingStatus } from "hooks/useVotingStatus";
import { Check } from "react-feather";
import { useAppDispatch, useAppSelector } from "state/hooks";
import { addPendingVote, removePendingVote, selectPendingVotes, selectSelectedLock } from "state/voting/slice";
import styled from "styled-components";
import { colors } from "theme/colors";
import { Flex, Text } from "ui/src";
const Button = styled.button`
  all: unset;
  display: flex;
  align-items: center;
  gap: 4px;
  padding: 8px 12px;
  border: 1px solid ${({ theme, selected }) => selected ? theme.surface3 : theme.surface3};
  border-radius: 12px;
  background-color: ${({ theme, selected }) => selected ? theme.surface1Hovered : theme.surface1};
  cursor: pointer;
  transition: all 0.2s ease-in-out;

  &:hover {
    background-color: ${({ theme }) => theme.surface1Hovered};
  }
`;
export default function PopoverAllVotes({ gauge }) {
  const dispatch = useAppDispatch();
  const account = useAccount();
  const pendingVotes = useAppSelector(selectPendingVotes);
  const selectedLock = useAppSelector(selectSelectedLock);
  const { data: userLocks } = useVeABXUserLocks(account.address);
  if (!gauge) {
    return <Flex row gap="$gap4" alignItems="center">
        <Text variant="body3" color="$neutral3">
          No gauge
        </Text>
      </Flex>;
  }
  const isSelected = pendingVotes.some((vote) => vote.poolAddress === gauge.poolId);
  const userOwnedLocks = userLocks?.filter((lock) => {
    const isOwner = lock.owner.toLowerCase() === account.address?.toLowerCase();
    const isNotExpired = lock.permanent || parseInt(lock.lockEnd) * 1e3 > Date.now();
    return isOwner && isNotExpired;
  }) || [];
  const { lockStatuses } = useVotingStatus(userOwnedLocks);
  const availableLocks = userOwnedLocks.filter((lock) => {
    const lockStatus = lockStatuses.find((status) => status.tokenId === lock.id);
    const hasVoted = lockStatus?.hasVoted || false;
    return !hasVoted;
  });
  const handleToggleSelect = () => {
    if (isSelected) {
      dispatch(removePendingVote(gauge.poolId));
    } else {
      dispatch(
        addPendingVote({
          poolAddress: gauge.poolId,
          poolId: gauge.id,
          weight: 1,
          pool: gauge
        })
      );
    }
  };
  if (availableLocks.length === 0) {
    const hasLocks = userOwnedLocks.length > 0;
    const allVoted = hasLocks && lockStatuses.every((status) => status.hasVoted);
    return <Flex row gap="$gap4" alignItems="center">
        <Text variant="body3" color="$neutral3">
          {allVoted ? "All locks voted" : "No locks"}
        </Text>
      </Flex>;
  }
  return <>
      {!selectedLock ? <Text
    px={"$spacing12"}
    py={"$spacing8"}
    borderRadius={"$rounded12"}
    borderWidth={1}
    borderColor={"$surface2"}
    variant="body3"
    color="$neutral3"
    cursor="not-allowed"
  >
          Select lock first
        </Text> : <Button selected={isSelected} onClick={handleToggleSelect}>
          <Text variant="buttonLabel4">{isSelected ? "Ready to vote" : "Select"}</Text>
          {isSelected && <Check size={14} color={colors.absGreen} />}
        </Button>}
    </>;
}
